//! AUTO-GENERATED by `scripts/gen_property_tables.py` — do not edit by hand.
//!
//! Per-game-version exposed-PROPERTY tables for the entities the replay
//! decoder walks. An EntityCreate (0x05) state stream carries the entity's
//! client-visible properties in BigWorld exposed-index order: the property
//! list inheritance-ordered (interfaces, then the entity's own), filtered by
//! the replicated Flags, and stably sorted by wire size. The index drifts
//! whenever the entity defs change, so `build.rs` resolves the payloads it
//! decodes (`shipConfig`, `crewModifiersCompactParams`) BY NAME from this
//! table and walks the fixed/variable split off each entry's wire width.
//!
//! Source of truth: the client's `entity_defs` XML, extracted from a local
//! game install with the vendored CLI (offline; CI never runs the generator):
//!
//! ```text
//! cargo build -p game-assets --release
//! ./target/release/game-assets.exe -g <game_dir> extract \
//!     -o scripts/experiments/out/defs "/scripts/entity_defs/**" "/scripts/entities*"
//! python scripts/gen_property_tables.py            # regenerate this file
//! python scripts/gen_property_tables.py --defs <defs_root> --version 15.9.0
//!                                           # offline validation only
//! ```

/// One client-visible property: its entity-def name and wire width.
pub struct PropertyEntry {
    pub name: &'static str,
    /// Fixed wire width in bytes (1/2/4/8/12); `None` = variable-width
    /// (BLOB/STRING/ARRAY/USER_TYPE/... — self-describing on the wire).
    pub fixed_width: Option<u8>,
}

/// One game version's Vehicle exposed-property map, in exposed-index order.
pub struct VehiclePropertyTable {
    /// The number of properties in the EntityCreate state (the u8 after the
    /// frame's u32 declared length).
    pub count: u8,
    /// Exposed-index-ordered property list; the position IS the wire index.
    pub properties: &'static [PropertyEntry],
    /// Exposed index of the `shipConfig` USER_TYPE property (u8 length + blob).
    pub ship_config: u8,
    /// Exposed index of the `crewModifiersCompactParams` FIXED_DICT property.
    pub crew_modifiers_compact_params: u8,
}

