/// Resolve the property table for a parsed client version: the newest pinned
/// row of the SAME (major, minor) era at or below the requested patch.
/// `None` = no map pinned for this era (the caller skips build decoding).
pub fn vehicle_property_table_for_version(
    version: (u32, u32, u32),
) -> Option<&'static VehiclePropertyTable> {
    let (major, minor, patch) = version;
    let mut best: Option<((u16, u16, u16), &'static VehiclePropertyTable)> = None;
    for (key, table) in VEHICLE_PROPERTY_TABLES {
        if u32::from(key.0) != major || u32::from(key.1) != minor {
            continue;
        }
        if u32::from(key.2) > patch {
            continue;
        }
        match best {
            Some((best_key, _)) if best_key >= *key => {},
            _ => best = Some((*key, table)),
        }
    }
    best.map(|(_, table)| table)
}
